<?php
ini_set("display_errors","1"); ini_set("log_errors","0");
require __DIR__.'/bootstrap.php';require_perm('payments.view');$me=user();$branchScope=is_admin()?'':' AND (s.branch_id='.(int)require_branch().' OR s.to_branch_id='.(int)require_branch().')';
$pdo->exec("UPDATE payment_plans SET status='Overdue' WHERE status='Pending' AND due_date<CURDATE()");
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();require_perm('payments.record');
    if(isset($_POST['create'])){
        $shipmentId=(int)$_POST['shipment_id'];$amount=max(0.01,(float)$_POST['amount']);
        $check=$pdo->prepare('SELECT id,balance_mgq,total,extra,paid_dxb FROM shipments s WHERE s.id=?'.$branchScope);$check->execute([$shipmentId]);$ship=$check->fetch();
        if(!$ship){flash('danger','Shipment not found in your branch.');redirect('payment_plans.php');}
        if($amount>max(0,(float)$ship['balance_mgq'])){flash('danger','Plan amount cannot exceed the shipment balance ('.money($ship['balance_mgq']).').');redirect('payment_plans.php');}
        $pdo->prepare('INSERT INTO payment_plans(shipment_id,due_date,amount,notes,created_by) VALUES(?,?,?,?,?)')->execute([$shipmentId,$_POST['due_date'],$amount,trim($_POST['notes']),$me['id']]);
        flash('success','Payment plan installment added.');
    }elseif(isset($_POST['generate'])){
        $shipmentId=(int)$_POST['shipment_id'];$count=max(2,min(12,(int)($_POST['count']??2)));$interval=max(1,min(60,(int)($_POST['interval']??7)));$first=preg_match('/^\d{4}-\d{2}-\d{2}$/',$_POST['first_due']??'')?$_POST['first_due']:date('Y-m-d');
        $s=$pdo->prepare('SELECT id,balance_mgq,awb FROM shipments s WHERE s.id=?'.$branchScope);$s->execute([$shipmentId]);$ship=$s->fetch();
        if(!$ship){flash('danger','Shipment not found in your branch.');redirect('payment_plans.php');}
        $totalBalance=max(0,(float)$ship['balance_mgq']);if($totalBalance<=0){flash('danger','This shipment has no outstanding balance.');redirect('payment_plans.php');}
        $base=round($totalBalance/$count,2);$ins=$pdo->prepare('INSERT INTO payment_plans(shipment_id,due_date,amount,notes,created_by) VALUES(?,?,?,?,?)');
        $pdo->beginTransaction();try{for($i=0;$i<$count;$i++){$due=date('Y-m-d',strtotime($first.' +'.($i*$interval).' days'));$a=$i===$count-1?round($totalBalance-($count-1)*$base,2):$base;if($a>0)$ins->execute([$shipmentId,$due,$a,'Auto-generated instalment '.($i+1).' of '.$count.' · '.e($ship['awb']),$me['id']]);}$pdo->commit();flash('success','Payment plan generated for '.$count.' instalments of '.money($base).' ('.money($totalBalance).' balance).');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Plan could not be generated.');}
        redirect('payment_plans.php');
    }elseif(isset($_POST['update'])){
        $pdo->prepare('UPDATE payment_plans SET due_date=?,amount=?,notes=?,status=? WHERE id=?')->execute([$_POST['due_date'],max(0.01,(float)$_POST['amount']),trim($_POST['notes']),$_POST['status'],(int)$_POST['id']]);
        flash('success','Installment updated.');
    }elseif(isset($_POST['delete'])){
        $pdo->prepare("DELETE FROM payment_plans WHERE id=? AND status<>'Paid'")->execute([(int)$_POST['id']]);
        flash('success','Installment deleted.');
    }elseif(isset($_POST['mark'])){
        $status=$_POST['status']??'Paid';
        $plan=$pdo->prepare('SELECT pp.*,s.balance_mgq,s.total,s.extra,s.paid_dxb,s.branch_id,s.to_branch_id FROM payment_plans pp JOIN shipments s ON s.id=pp.shipment_id WHERE pp.id=?');$plan->execute([(int)$_POST['id']]);$p=$plan->fetch();
        if(!$p){flash('danger','Plan not found.');redirect('payment_plans.php');}
        if($status==='Paid'){
            $remaining=max(0,(float)$p['balance_mgq']);
            if((float)$p['amount']>$remaining){flash('danger','Installment is larger than the remaining shipment balance ('.money($remaining).'); update the plan first.');redirect('payment_plans.php');}
            $payLocation=$_POST['location']??'MGQ';$method=$_POST['method']??'Other';$payBranch=(int)$p['branch_id'];if($payLocation==='MGQ'&&(int)($p['to_branch_id']??0)>0)$payBranch=(int)$p['to_branch_id'];$bankId=0;if($method==='Bank Transfer'||(int)($_POST['bank_account_id']??0)>0){$bankId=bank_account_id_for_branch((int)($_POST['bank_account_id']??0),$payBranch);if(!$bankId){flash('danger','Select an active bank account for the '.e($payLocation==='MGQ'?'destination':'origin').' branch.');redirect('payment_plans.php');}}
            $pdo->beginTransaction();
            try{
                $ref='PLAN-'.str_pad((string)$p['id'],5,'0',STR_PAD_LEFT);
                $pdo->prepare('INSERT INTO payments(shipment_id,bank_account_id,amount,location,payment_method,reference_no,notes,received_by,paid_at) VALUES(?,?,?,?,?,?,?,?,NOW())')->execute([(int)$p['shipment_id'],$bankId?:null,(float)$p['amount'],$payLocation,$method,$ref,'Payment plan installment · '.trim($p['notes']??''),$me['id']]);$paymentId=(int)$pdo->lastInsertId();if($bankId)add_bank_transaction($bankId,'Payment','payments',$paymentId,(float)$p['amount'],date('Y-m-d H:i:s'));
                $newPaid=(float)$p['paid_dxb']+(float)$p['amount'];
                $shipStatus=$newPaid>=((float)$p['total']+(float)$p['extra'])?'Paid':'Partially Paid';
                $pdo->prepare('UPDATE shipments SET paid_dxb=?,payment_receive=? WHERE id=?')->execute([$newPaid,$shipStatus,(int)$p['shipment_id']]);
                $pdo->prepare("UPDATE payment_plans SET status='Paid',paid_at=NOW() WHERE id=?")->execute([(int)$p['id']]);
                $pdo->commit();flash('success','Installment marked paid — the payment was recorded against the shipment and the balance updated.');
            }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Payment could not be recorded for this installment.');}
        }else{
            $pdo->prepare('UPDATE payment_plans SET status=?,paid_at=NULL WHERE id=?')->execute([$status,(int)$p['id']]);
            flash('success','Installment status updated.');
        }
    }
    redirect('payment_plans.php');
}
$rows=$pdo->query('SELECT pp.id,pp.shipment_id,pp.due_date,pp.amount,pp.notes,pp.status,pp.paid_at,pp.created_by,pp.created_at,s.awb,s.sender,s.receiver,s.total,s.extra,s.paid_dxb,s.balance_mgq,s.branch_id,s.to_branch_id,a.name airline,u.name customer_name FROM payment_plans pp JOIN shipments s ON s.id=pp.shipment_id JOIN airlines a ON a.id=s.airline_id LEFT JOIN users u ON u.id=s.customer_id'.(is_admin()?'':' WHERE (s.branch_id='.(int)require_branch().' OR s.to_branch_id='.(int)require_branch().')').' ORDER BY pp.status=\'Paid\',CASE pp.status WHEN \'Overdue\' THEN 0 WHEN \'Pending\' THEN 1 ELSE 2 END,pp.due_date')->fetchAll();
$pending=array_sum(array_column(array_filter($rows,fn($r)=>$r['status']!=='Paid'),'amount'));$overdue=array_sum(array_column(array_filter($rows,fn($r)=>$r['status']==='Overdue'),'amount'));$paid=array_sum(array_column(array_filter($rows,fn($r)=>$r['status']==='Paid'),'amount'));
$ships=$pdo->query('SELECT id,awb,sender,receiver,balance_mgq FROM shipments s WHERE status<>\'Cancelled\''.(is_admin()?'':' AND (branch_id='.(int)require_branch().' OR to_branch_id='.(int)require_branch().')').' ORDER BY shipment_date DESC')->fetchAll();$banks=$pdo->query('SELECT a.id,a.name,a.bank_name,a.account_number,a.branch_id,br.name branch_name FROM bank_accounts a JOIN branches br ON br.id=a.branch_id WHERE a.active=1'.(is_admin()?'':' AND a.branch_id='.(int)require_branch()).' ORDER BY a.name')->fetchAll();
$title='Payment plans';require __DIR__.'/partials/header.php';
?>
<div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-4"><div><h1 class="h3 fw-bold mb-1">Payment Plans</h1><p class="text-secondary mb-0">Split a shipment balance into due instalments so collections are never missed.</p></div><div class="d-flex gap-2"><?php if(can('payments.record')):?><button class="btn btn-outline-primary" data-bs-toggle="modal" data-bs-target="#genPlan"><i class="bi bi-magic"></i> Generate plan</button><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#plan"><i class="bi bi-plus-lg"></i> Add installment</button><?php endif?></div></div>
<div class="row g-3 mb-4"><div class="col-6 col-md-3"><div class="card p-3"><small class="text-secondary">To collect</small><strong class="h5 text-danger mb-0"><?=money($pending)?></strong></div></div><div class="col-6 col-md-3"><div class="card p-3"><small class="text-secondary">Overdue</small><strong class="h5 text-warning mb-0"><?=money($overdue)?></strong></div></div><div class="col-6 col-md-3"><div class="card p-3 border-start border-success border-4"><small class="text-secondary">Collected</small><strong class="h5 text-success mb-0"><?=money($paid)?></strong></div></div><div class="col-6 col-md-3"><div class="card p-3"><small class="text-secondary">Installments</small><strong class="h5 mb-0"><?=count($rows)?></strong></div></div></div>
<div class="card p-3 p-lg-4"><input class="form-control mb-3" style="max-width:420px" data-table-search placeholder="Search AWB, sender, or notes"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Due date</th><th>AWB / customer</th><th>Cargo / paid</th><th>Installment</th><th>Notes</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=app_date($r['due_date'])?><?php if($r['status']==='Overdue'):?><small class="d-block text-danger">Overdue</small><?php endif?></td><td class="fw-semibold"><?=e($r['awb'])?><small class="d-block text-secondary"><?=e($r['sender'])?> → <?=e($r['receiver'])?></small></td><td><?=money($r['total'])?><small class="d-block text-success">Paid <?=money($r['paid_dxb'])?></small></td><td class="fw-bold"><?=money($r['amount'])?></td><td><?=e($r['notes']?:'—')?></td><td><span class="status status-<?=strtolower($r['status'])?>"><?=e($r['status'])?></span></td><td class="text-nowrap"><?php if($r['status']!=='Paid'):?><button class="btn btn-sm btn-outline-secondary me-1" data-bs-toggle="modal" data-bs-target="#edit<?=$r['id']?>">Edit</button><button class="btn btn-sm btn-success me-1" data-bs-toggle="modal" data-bs-target="#mark<?=$r['id']?>">Paid</button><?php else:?><small class="text-secondary"><?=app_date($r['paid_at'])?></small><?php endif?> <?php if($r['status']!=='Paid'):?><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger" name="delete" data-confirm="Delete this installment?">Delete</button></form><?php endif?></td></tr>
<?php if($r['status']!=='Paid'&&can('payments.record')):?><div class="modal fade" id="edit<?=$r['id']?>"><div class="modal-dialog"><form method="post" class="modal-content"><div class="modal-header"><h2 class="h5 mb-0">Edit installment</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><label class="form-label">Due date</label><input class="form-control mb-3" type="date" name="due_date" value="<?=e($r['due_date'])?>" required><label class="form-label">Amount</label><input class="form-control mb-3" type="number" min=".01" step=".01" name="amount" value="<?=e($r['amount'])?>" required><label class="form-label">Notes</label><input class="form-control mb-3" name="notes" value="<?=e($r['notes'])?>"><label class="form-label">Status</label><select class="form-select mb-3" name="status"><?php foreach(['Pending','Overdue','Cancelled'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach?></select></div><div class="modal-footer"><button class="btn btn-primary" name="update">Save changes</button></div></form></div></div><div class="modal fade plan-mark-modal" id="mark<?=$r['id']?>"><div class="modal-dialog"><form method="post" class="modal-content"><div class="modal-header"><h2 class="h5 mb-0">Record payment · <?=e($r['awb'])?></h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="status" value="Paid"><div class="alert alert-light border small mb-3">Installment: <strong><?=money($r['amount'])?></strong> · Balance: <?=money($r['balance_mgq'])?></div><label class="form-label">Payment location</label><select class="form-select mb-3" name="location"><option>DXB</option><option>MGQ</option></select><label class="form-label">Method</label><select class="form-select mb-3" name="method"><option>Cash</option><option>Bank Transfer</option><option>Mobile Money</option><option>Card</option><option>Other</option></select><label class="form-label">Deposit to bank account <small class="text-secondary">(required for Bank Transfer · optional for other methods — adds this payment to the bank statement)</small></label><select class="form-select mb-3" name="bank_account_id"><option value="">Select bank account</option><?php foreach($banks as $b):if(is_admin()||(int)$b['branch_id']===(int)($r['branch_id']??0)||(int)$b['branch_id']===(int)($r['to_branch_id']??0)):?><option value="<?=$b['id']?>"><?=e($b['name'].' · '.$b['bank_name'].' · '.$b['account_number'].(!empty($b['branch_name'])?' ('.$b['branch_name'].')':''))?></option><?php endif;endforeach?></select></div><div class="modal-footer"><button class="btn btn-success" name="mark">Record payment</button></div></form></div></div><?php endif?>
<?php endforeach?><?php if(!$rows):?><tr><td colspan="7" class="text-center text-secondary py-5">No payment plans yet — add an installment to get started.</td></tr><?php endif?></tbody></table></div></div>
<?php if(can('payments.record')):?><div class="modal fade" id="genPlan"><div class="modal-dialog"><form method="post" class="modal-content"><div class="modal-header"><h2 class="h5 mb-0">Generate payment plan</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf()?>"><label class="form-label">Shipment</label><select class="form-select mb-3" name="shipment_id" required><?php foreach($ships as $s):?><option value="<?=$s['id']?>"><?=e($s['awb'].' · '.$s['sender'].' · balance '.money($s['balance_mgq']))?></option><?php endforeach?></select><div class="row g-2"><div class="col-4"><label class="form-label">Instalments</label><input class="form-control mb-3" type="number" min="2" max="12" name="count" value="2" required></div><div class="col-4"><label class="form-label">Days between</label><input class="form-control mb-3" type="number" min="1" max="60" name="interval" value="7" required></div><div class="col-4"><label class="form-label">First due</label><input class="form-control mb-3" type="date" name="first_due" value="<?=date('Y-m-d',strtotime('+7 days'))?>" required></div></div><p class="text-secondary small mb-0">The outstanding balance is split evenly into the instalments — the last one keeps any remainder.</p></div><div class="modal-footer"><button class="btn btn-primary" name="generate"><i class="bi bi-magic"></i> Generate plan</button></div></form></div></div><div class="modal fade" id="plan"><div class="modal-dialog"><form method="post" class="modal-content"><div class="modal-header"><h2 class="h5 mb-0">Add payment installment</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf()?>"><label class="form-label">Shipment</label><select class="form-select mb-3" name="shipment_id" required><?php foreach($ships as $s):?><option value="<?=$s['id']?>"><?=e($s['awb'].' · '.$s['sender'].' · balance '.money($s['balance_mgq']))?></option><?php endforeach?></select><label class="form-label">Due date</label><input class="form-control mb-3" type="date" name="due_date" value="<?=date('Y-m-d',strtotime('+7 days'))?>" required><label class="form-label">Amount</label><input class="form-control mb-3" type="number" min=".01" step=".01" name="amount" placeholder="e.g. 150.00" required><label class="form-label">Notes</label><input class="form-control" name="notes" placeholder="e.g. First instalment — 50%"></div><div class="modal-footer"><button class="btn btn-primary" name="create">Add installment</button></div></form></div></div><?php endif?>
<script>(function(){document.querySelectorAll('.plan-mark-modal').forEach(m=>{const mt=m.querySelector('[name="method"]'),bk=m.querySelector('[name="bank_account_id"]');if(!mt||!bk)return;const sync=()=>{bk.required=mt.value==='Bank Transfer';};mt.addEventListener('change',sync);sync();})})();</script>
